def transform(grid):
    sep = next(r for r, row in enumerate(grid) if len(set(row)) == 1)
    top, bottom = grid[:sep], grid[sep + 1:]

    def background(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    top_bg = background(top)
    bottom_bg = background(bottom)
    h = min(len(top), len(bottom))
    w = min(len(top[0]), len(bottom[0]))

    return [
        [3 if (top[r][c] != top_bg) == (bottom[r][c] != bottom_bg)
         else bottom_bg for c in range(w)]
        for r in range(h)
    ]
